package com.denfense.server.domain;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) @Table(name="battle_settlements",uniqueConstraints={@UniqueConstraint(name="uk_battle_session",columnNames="battle_session_id"),@UniqueConstraint(name="uk_battle_request",columnNames="request_id")})
public class BattleSettlement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="battle_session_id",nullable=false,unique=true) private String battleSessionId; @Column(nullable=false,unique=true) private String requestId; @Column(nullable=false) private String summaryHash; @Column(nullable=false) private String balanceVersion; @Column(nullable=false) private String contentHash; @Enumerated(EnumType.STRING) @Column(nullable=false) private BattleResult result; private int finalWave; private LocalDateTime startedAt,finishedAt,createdAt,updatedAt; @Enumerated(EnumType.STRING) private SettlementStatus status;
 public BattleSettlement(String sid,String rid,String sh,String bv,String ch,BattleResult r,int wave,LocalDateTime st,LocalDateTime ft){battleSessionId=sid;requestId=rid;summaryHash=sh;balanceVersion=bv;contentHash=ch;result=r;finalWave=wave;startedAt=st;finishedAt=ft;createdAt=LocalDateTime.now();updatedAt=createdAt;status=SettlementStatus.ACCEPTED;}
}
